class Account {
  private decimal balance;                    // инкапсуляция
  public Account(decimal initial) => balance = initial;
  public void Withdraw(decimal amount) {
    if (amount > balance) throw new InvalidOperationException("insufficient");
    balance -= amount;
  }
  public decimal Balance => balance;
}
var acc = new Account(1000m);   // объект — экземпляр класса
acc.Withdraw(200m);
Console.WriteLine(acc.Balance); // 800
```

