```cpp
// Race condition
int counter = 0;
void increment() {
    for (int i = 0; i < 100000; ++i)
        counter++;  // НЕ атомарно — data race, UB
}
std::thread t1(increment), t2(increment);
t1.join(); t2.join();
// counter < 200000 (потерянные обновления)

// Решение 1: std::atomic
std::atomic<int> counter{0};
void increment() {
    for (int i = 0; i < 100000; ++i)
        counter.fetch_add(1, std::memory_order_relaxed);  // атомарно
}

// Решение 2: std::mutex
std::mutex m;
int counter = 0;
void increment() {
    for (int i = 0; i < 100000; ++i) {
        std::lock_guard<std::mutex> lock(m);
        counter++;  // защищено мьютексом
    }
}

// Компиляция с TSan: g++ -fsanitize=thread -g main.cpp
```

