Dictionary<int, int> cache = new();
int Fib(int n) {
    if (cache.TryGetValue(n, out var v)) return v;
    var r = n <= 1 ? n : Fib(n - 1) + Fib(n - 2);
    cache[n] = r;
    return r;
}
